// Real screenshots of the plugin's admin screens on the local test site (build/wp).
// Authenticates with cookies generated by WP-CLI for user 1 of the throw-away site.
//   node tools/screenshots.mjs <site> <cookie-json-file> <out-dir>
import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import path from 'node:path';

const require = createRequire( path.resolve( 'build/node/package.json' ) );
const puppeteer = require( 'puppeteer-core' );
const [ site, cookieFile, out ] = process.argv.slice( 2 );
mkdirSync( out, { recursive: true } );
const cookies = JSON.parse( readFileSync( cookieFile, 'utf8' ) );

const browser = await puppeteer.launch( {
	executablePath: '/usr/bin/google-chrome',
	headless: true,
	userDataDir: path.resolve( 'build/chrome-profile' ),
	args: [ '--no-first-run', '--hide-scrollbars', '--lang=en-US', '--disable-gpu' ],
	defaultViewport: { width: 1280, height: 720, deviceScaleFactor: 1 },
} );
const page = await browser.newPage();
const host = new URL( site ).hostname;
await page.setCookie( ...cookies.map( ( c ) => ( { ...c, domain: host } ) ) );
const admin = ( q ) => `${ site }/wp-admin/tools.php?page=pnscripts-waymend-lite${ q }`;
const errors = [];
if ( process.env.ONLY === 'bg' ) {
	await page.goto( admin( '&tab=rules&test_url=' + encodeURIComponent( '/about' ) ), { waitUntil: 'networkidle2' } );
	await shot( 'redirects-list-bg' );
	await browser.close();
	process.exit( 0 );
}
page.on( 'pageerror', ( e ) => errors.push( e.message ) );

async function shot( name ) {
	await page.addStyleTag( { content: '#wpadminbar{display:none!important} html.wp-toolbar{padding-top:0!important} #wpfooter{display:none}' } );
	await page.screenshot( { path: `${ out }/${ name }.png` } );
	console.log( 'saved', name );
}

// 1. Redirect list with the URL tester tracing a chain.
await page.goto( admin( '&tab=rules&test_url=' + encodeURIComponent( '/about' ) ), { waitUntil: 'networkidle2' } );
if ( ! ( await page.$( '.waymend-trace' ) ) ) throw new Error( 'tester did not render' );
await shot( 'redirects-list' );

// 2. "Redirect this" from the 404 log: opens the form with source and suggested target.
await page.goto( admin( '&tab=log' ), { waitUntil: 'networkidle2' } );
await shot( '404-log' );
const link = await page.$$eval( '.row-actions .redirect a', ( as ) => as.map( ( a ) => ( { href: a.href, row: a.closest( 'tr' ).innerText } ) ) );
const target = link.find( ( l ) => l.row.includes( '/how-to-store-summer-tyres-2' ) ) || link[ 0 ];
await page.goto( target.href, { waitUntil: 'networkidle2' } );
const suggested = await page.$eval( '#waymend-target', ( el ) => el.value );
console.log( 'suggested target:', suggested );
await shot( 'redirect-this' );
await Promise.all( [ page.waitForNavigation( { waitUntil: 'networkidle2' } ), page.click( '#submit' ) ] );
const notice = await page.$eval( '.notice', ( el ) => el.innerText );
console.log( 'after save:', notice.trim() );

// 3. Loop detection: try to save a rule that points back.
await page.goto( admin( '&tab=rules&action=new' ), { waitUntil: 'networkidle2' } );
await page.type( '#waymend-source', '/contact' );
await page.type( '#waymend-target', '/kontakti' );
await Promise.all( [ page.waitForNavigation( { waitUntil: 'networkidle2' } ), page.click( '#submit' ) ] );
await shot( 'loop-refused' );

// 4b. "Check old URLs" with the old site's addresses (a mix of every result).
await page.goto( admin( '&tab=import' ), { waitUntil: 'networkidle2' } );
await page.type( '#waymend-check-urls', [
	'https://www.old-tyre-shop.example/kontakti',
	'https://www.old-tyre-shop.example/old-shop/wheels/alloy-17',
	'https://www.old-tyre-shop.example/blog/2019/11/winter-tyre-guide/',
	'https://www.old-tyre-shop.example/discontinued/rim-cleaner',
	'https://www.old-tyre-shop.example/tyre-pressure',
	'https://www.old-tyre-shop.example/gift-cards',
	'https://www.old-tyre-shop.example/about',
	'https://www.old-tyre-shop.example/catalogue/winter-tyres-2023',
].join( '\n' ) );
await Promise.all( [ page.waitForNavigation( { waitUntil: 'networkidle2' } ), page.click( '#waymend-check input[type=submit]' ) ] );
await page.evaluate( () => document.getElementById( 'waymend-check' ).scrollIntoView() );
await page.evaluate( () => window.scrollBy( 0, -40 ) );
await shot( 'check-old-urls' );

// 5. Bulgarian admin (site language bg_BG) is taken by screenshots.sh with ONLY=bg.
// 6. Settings.
await page.goto( admin( '&tab=settings' ), { waitUntil: 'networkidle2' } );
await shot( 'settings' );

await browser.close();
if ( errors.length ) {
	console.error( 'page errors:', errors );
	process.exit( 1 );
}
